import{_ as s,o as a,c as n,a0 as i}from"./chunks/framework.OED5XGjC.js";const f=JSON.parse('{"title":"Hand off work between sessions","description":"","frontmatter":{},"headers":[],"relativePath":"how-to/handoff.md","filePath":"how-to/handoff.md"}'),o={name:"how-to/handoff.md"};function t(d,e,c,l,p,r){return a(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="hand-off-work-between-sessions" tabindex="-1">Hand off work between sessions <a class="header-anchor" href="#hand-off-work-between-sessions" aria-label="Permalink to &quot;Hand off work between sessions&quot;">​</a></h1><p>Attach resumable state to any item at the end of a working session, then pull the minimal context to restart it later.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">myco</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> handoff</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> T-012</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --note</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;parser done, emitter next&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --actor</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> devin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --session</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cli:abc123</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">myco</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> resume</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> T-012</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # minimal context block to restart work</span></span></code></pre></div><h2 id="myco-handoff-id" tabindex="-1"><code>myco handoff &lt;id&gt;</code> <a class="header-anchor" href="#myco-handoff-id" aria-label="Permalink to &quot;\`myco handoff &lt;id&gt;\`&quot;">​</a></h2><p>Appends a dated entry to <code>handoffs/&lt;ID&gt;.md</code> — works on every item kind (<code>T-</code>, <code>I-</code>, <code>P-</code>, <code>ADR-</code>, <code>PL-</code>), live or archived. The item must exist; the note is required.</p><ul><li><code>--note &quot;…&quot;</code> — the handoff text (done/next/open). <code>-</code> reads stdin.</li><li><code>--actor &lt;id&gt;</code> — who wrote it (<code>devin</code>, <code>human:luis</code>; default <code>cli</code>).</li><li><code>--session &lt;id&gt;</code> — provenance, any id string (a sepia session id, <code>cli:&lt;pid&gt;</code>, …). Recorded verbatim, never interpreted.</li></ul><p>Each call is one appended <code>##</code> entry and one commit (<code>chore: handoff &lt;id&gt;</code>). Files are append-only — history inside a file is never rewritten.</p><h2 id="myco-resume-id-last-n" tabindex="-1"><code>myco resume &lt;id&gt; [--last N]</code> <a class="header-anchor" href="#myco-resume-id-last-n" aria-label="Permalink to &quot;\`myco resume &lt;id&gt; [--last N]\`&quot;">​</a></h2><p>Emits the restart context as a compact prompt block:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>I-003 in-progress pri:high owner:devin #index memory leak</span></span>
<span class="line"><span>in: issues/issue-0003-memory-leak.md</span></span>
<span class="line"><span>blocks:</span></span>
<span class="line"><span>  T-010 store layer</span></span>
<span class="line"><span>handoffs:</span></span>
<span class="line"><span>2026-10-29 · devin · session:cli:abc123</span></span>
<span class="line"><span>  Done: repro. Next: fix.</span></span>
<span class="line"><span>open checklist:</span></span>
<span class="line"><span>  - [ ] add regression test</span></span></code></pre></div><p><code>--json</code> gives <code>{item, location, blocks_titles, handoffs[], open_checklist}</code> — the same data for machines. <code>--last N</code> shows only the latest N handoff entries (default 10).</p><p><code>myco item show &lt;id&gt;</code> surfaces a <code>handoffs: N</code> count; <code>myco check</code> keeps <code>handoffs/</code> honest — files for removed items are archived to <code>handoffs/archive/</code> by <code>--fix</code>, and malformed entries are parse findings.</p><p>For the sepia-side wiring (session hooks calling these verbs), see <a href="./session-continuity.html">session continuity with sepia</a>.</p>`,13)])])}const k=s(o,[["render",t]]);export{f as __pageData,k as default};
